    final java.util.List<ICollisionEntity> entities = this.collisionEntities.get(collision);
    if (entities == null) {
      return null;
    }

    for (final ICollisionEntity collisionEntity : entities) {
      if (!canCollide(entity, collisionEntity)) {
        continue;
